--
-- Name: check_fingerprint_banned(character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_fingerprint_banned(p_canvas_hash character varying DEFAULT NULL::character varying, p_worldid_nullifier_hash character varying DEFAULT NULL::character varying, p_combined_hash character varying DEFAULT NULL::character varying) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
  is_banned BOOLEAN := false;
BEGIN
  -- Verificar por canvas hash
  IF p_canvas_hash IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM digital_fingerprints
      WHERE canvas_hash = p_canvas_hash AND is_banned = true
    ) INTO is_banned;

    IF is_banned THEN
      RETURN true;
    END IF;
  END IF;

  -- Verificar por WorldID nullifier hash
  IF p_worldid_nullifier_hash IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM permanent_bans
      WHERE worldid_nullifier_hash = p_worldid_nullifier_hash
        AND is_active = true
    ) INTO is_banned;

    IF is_banned THEN
      RETURN true;
    END IF;

    -- También verificar en digital_fingerprints
    SELECT EXISTS (
      SELECT 1 FROM digital_fingerprints
      WHERE worldid_nullifier_hash = p_worldid_nullifier_hash
        AND is_banned = true
    ) INTO is_banned;

    IF is_banned THEN
      RETURN true;
    END IF;
  END IF;

  -- Verificar por combined hash
  IF p_combined_hash IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM digital_fingerprints
      WHERE combined_hash = p_combined_hash AND is_banned = true
    ) INTO is_banned;

    IF is_banned THEN
      RETURN true;
    END IF;

    SELECT EXISTS (
      SELECT 1 FROM permanent_bans
      WHERE combined_hash = p_combined_hash AND is_active = true
    ) INTO is_banned;
  END IF;

  RETURN is_banned;
END;
$$;


--
-- Name: check_rate_limit(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_rate_limit(p_user_id uuid, p_ip_address text, p_endpoint text, p_max_requests integer DEFAULT 100) RETURNS TABLE(allowed boolean, remaining_requests integer, reset_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_window_start TIMESTAMP WITH TIME ZONE;
    v_window_end TIMESTAMP WITH TIME ZONE;
    v_request_count INTEGER;
    v_remaining INTEGER;
    v_allowed BOOLEAN;
BEGIN
    -- Definir ventana de tiempo (1 minuto)
    v_window_start := date_trunc('minute', NOW());
    v_window_end := v_window_start + INTERVAL '1 minute';

    -- Buscar o crear registro de rate limit
    SELECT
        request_count,
        CASE
            WHEN request_count < p_max_requests THEN TRUE
            ELSE FALSE
        END,
        p_max_requests - request_count,
        window_end
    INTO
        v_request_count,
        v_allowed,
        v_remaining,
        v_window_end
    FROM public.rate_limits
    WHERE
        user_id = p_user_id
        AND window_start = v_window_start
        AND endpoint = p_endpoint;

    -- Si no existe registro, crear uno nuevo
    IF NOT FOUND THEN
        INSERT INTO public.rate_limits (
            user_id,
            ip_address,
            endpoint,
            request_count,
            window_start,
            window_end
        ) VALUES (
            p_user_id,
            p_ip_address,
            p_endpoint,
            1,
            v_window_start,
            v_window_end
        );

        v_allowed := TRUE;
        v_remaining := p_max_requests - 1;
        v_window_end := v_window_start + INTERVAL '1 minute';
    ELSE
        -- Incrementar contador si está permitido
        IF v_allowed THEN
            UPDATE public.rate_limits
            SET
                request_count = request_count + 1,
                updated_at = NOW()
            WHERE
                user_id = p_user_id
                AND window_start = v_window_start
                AND endpoint = p_endpoint;
        END IF;
    END IF;

    RETURN QUERY SELECT
        v_allowed AS allowed,
        v_remaining AS remaining_requests,
        v_window_end AS reset_at;
END;
$$;


--
-- Name: check_summary_rate_limit(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_summary_rate_limit(p_user_id uuid, p_max_per_day integer DEFAULT 10) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_count INT;
BEGIN
  SELECT COUNT(*) INTO v_count
  FROM summary_requests
  WHERE user_id = p_user_id
    AND created_at >= CURRENT_DATE;

  RETURN v_count < p_max_per_day;
END;
$$;


--
-- Name: claim_world_id_reward(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_world_id_reward(user_id_param uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    user_tokens RECORD;
    world_id_amount INTEGER := 100;
BEGIN
    -- Obtener datos del usuario
    SELECT * INTO user_tokens FROM public.user_tokens WHERE user_id = user_id_param;

    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Usuario no encontrado'
        );
    END IF;

    -- Verificar si ya reclamó
    IF user_tokens.world_id_claimed THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Ya has reclamado tu recompensa de World ID'
        );
    END IF;

    -- Verificar límite mensual
    IF (user_tokens.monthly_earned + world_id_amount) > user_tokens.monthly_limit THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Límite mensual alcanzado (' || user_tokens.monthly_limit || ' CMPX)'
        );
    END IF;

    -- Actualizar tokens
    UPDATE public.user_tokens
    SET
        cmpx_balance = cmpx_balance + world_id_amount,
        monthly_earned = monthly_earned + world_id_amount,
        world_id_claimed = true,
        updated_at = NOW()
    WHERE user_id = user_id_param;

    -- Registrar transacción
    INSERT INTO public.transactions (
        user_id, transaction_type, token_type, amount,
        balance_before, balance_after, description
    ) VALUES (
        user_id_param, 'world_id_bonus', 'CMPX', world_id_amount,
        user_tokens.cmpx_balance, user_tokens.cmpx_balance + world_id_amount,
        'Recompensa por verificación World ID'
    );

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Recompensa de World ID reclamada: ' || world_id_amount || ' CMPX',
        'amount', world_id_amount,
        'new_balance', user_tokens.cmpx_balance + world_id_amount
    );
END;
$$;


