--
-- Name: create_annual_returns(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_annual_returns(investment_uuid uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  inv_record investments%ROWTYPE;
  return_amount NUMERIC;
  current_year INTEGER;
  i INTEGER;
  start_date TIMESTAMPTZ;
  end_date TIMESTAMPTZ;
  due_date TIMESTAMPTZ;
BEGIN
  -- Obtener datos de la inversión
  SELECT * INTO inv_record
  FROM investments
  WHERE id = investment_uuid AND status = 'active';

  IF NOT FOUND THEN
    RETURN;
  END IF;

  -- Calcular monto de retorno anual
  return_amount := inv_record.amount_mxn * (inv_record.return_percentage / 100.0);

  -- Crear retornos para los próximos 5 años
  current_year := EXTRACT(YEAR FROM NOW());

  FOR i IN 1..5 LOOP
    start_date := DATE_TRUNC('year', NOW()) + (i - 1) * INTERVAL '1 year';
    end_date := start_date + INTERVAL '1 year' - INTERVAL '1 day';
    due_date := start_date + INTERVAL '1 year';

    INSERT INTO investment_returns (
      investment_id,
      user_id,
      return_amount_mxn,
      return_percentage,
      return_period_start,
      return_period_end,
      due_date,
      status
    ) VALUES (
      investment_uuid,
      inv_record.user_id,
      return_amount,
      inv_record.return_percentage,
      start_date,
      end_date,
      due_date,
      'pending'
    )
    ON CONFLICT DO NOTHING;
  END LOOP;
END;
$$;


--
-- Name: create_assets_snapshot(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_assets_snapshot(p_couple_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    partner1_id UUID;
    partner2_id UUID;
    snapshot JSONB := '{}';
    partner1_assets JSONB;
    partner2_assets JSONB;
BEGIN
    -- Obtener IDs de partners
    SELECT partner_1_id, partner_2_id 
    INTO partner1_id, partner2_id
    FROM couple_profiles 
    WHERE id = p_couple_id;
    
    -- Crear snapshot de activos de partner 1
    SELECT jsonb_build_object(
        'cmpx_balance', COALESCE(cmpx_balance, 0),
        'gtk_balance', COALESCE(gtk_balance, 0),
        'nfts_count', (
            SELECT COUNT(*) 
            FROM user_nfts 
            WHERE user_id = partner1_id AND is_active = true
        )
    ) INTO partner1_assets
    FROM user_wallets 
    WHERE user_id = partner1_id;
    
    -- Crear snapshot de activos de partner 2
    SELECT jsonb_build_object(
        'cmpx_balance', COALESCE(cmpx_balance, 0),
        'gtk_balance', COALESCE(gtk_balance, 0),
        'nfts_count', (
            SELECT COUNT(*) 
            FROM user_nfts 
            WHERE user_id = partner2_id AND is_active = true
        )
    ) INTO partner2_assets
    FROM user_wallets 
    WHERE user_id = partner2_id;
    
    -- Combinar snapshots
    snapshot := jsonb_build_object(
        'partner_1', jsonb_build_object(
            'user_id', partner1_id,
            'assets', COALESCE(partner1_assets, '{}'::jsonb)
        ),
        'partner_2', jsonb_build_object(
            'user_id', partner2_id,
            'assets', COALESCE(partner2_assets, '{}'::jsonb)
        ),
        'frozen_at', NOW(),
        'total_value_estimate', (
            COALESCE((partner1_assets->>'cmpx_balance')::numeric, 0) +
            COALESCE((partner2_assets->>'cmpx_balance')::numeric, 0) +
            COALESCE((partner1_assets->>'gtk_balance')::numeric, 0) +
            COALESCE((partner2_assets->>'gtk_balance')::numeric, 0)
        )
    );
    
    RETURN snapshot;
END;
$$;


--
-- Name: FUNCTION create_assets_snapshot(p_couple_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_assets_snapshot(p_couple_id uuid) IS 'Crea snapshot JSONB de activos de pareja para congelar';


--
-- Name: create_couple_match(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_couple_match() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Check if there's a mutual like
    IF EXISTS (
        SELECT 1 FROM couple_profile_likes cpl1
        JOIN couple_profile_likes cpl2 ON cpl1.couple_profile_id = cpl2.liker_profile_id
        WHERE cpl1.liker_profile_id = NEW.couple_profile_id
        AND cpl2.couple_profile_id = NEW.liker_profile_id
    ) THEN
        -- Create match if it doesn't exist
        INSERT INTO couple_profile_matches (couple_profile1_id, couple_profile2_id)
        VALUES (NEW.couple_profile_id, NEW.liker_profile_id)
        ON CONFLICT (couple_profile1_id, couple_profile2_id) DO NOTHING;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: create_notification(text, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_notification(notification_type text, title text, body text, user_id uuid, data jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    result JSONB;
BEGIN
    INSERT INTO notification_history (
        notification_type,
        title,
        body,
        user_id,
        data,
        delivery_method,
        status
    ) VALUES (
        notification_type,
        title,
        body,
        user_id,
        data,
        'push',
        'pending'
    );

    result := jsonb_build_object(
        'success', true,
        'message', 'Notificación creada exitosamente'
    );

    RETURN result;
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', SQLERRM
    );
END;
$$;


--
-- Name: create_permanent_ban(uuid, character varying, character varying, text, uuid, character varying, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_permanent_ban(p_user_id uuid, p_canvas_hash character varying, p_combined_hash character varying, p_ban_reason text, p_banned_by uuid, p_worldid_nullifier_hash character varying DEFAULT NULL::character varying, p_severity text DEFAULT 'high'::text, p_evidence jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
  ban_id UUID;
  fingerprint_id UUID;
BEGIN
  -- Crear o actualizar fingerprint
  INSERT INTO digital_fingerprints (
    user_id,
    canvas_hash,
    worldid_nullifier_hash,
    combined_hash,
    is_banned,
    banned_at,
    ban_reason
  ) VALUES (
    p_user_id,
    p_canvas_hash,
    p_worldid_nullifier_hash,
    p_combined_hash,
    true,
    NOW(),
    p_ban_reason
  )
  ON CONFLICT (combined_hash) DO UPDATE SET
    is_banned = true,
    banned_at = NOW(),
    ban_reason = p_ban_reason,
    updated_at = NOW()
  RETURNING id INTO fingerprint_id;

  -- Crear baneo permanente
  INSERT INTO permanent_bans (
    user_id,
    fingerprint_ids,
    ban_reason,
    ban_type,
    severity,
    banned_by,
    worldid_nullifier_hash,
    canvas_hash,
    combined_hash,
    evidence
  ) VALUES (
    p_user_id,
    ARRAY[fingerprint_id],
    p_ban_reason,
    'manual',
    p_severity,
    p_banned_by,
    p_worldid_nullifier_hash,
    p_canvas_hash,
    p_combined_hash,
    p_evidence
  )
  RETURNING id INTO ban_id;

  -- Marcar usuario como baneado en profiles
  UPDATE profiles
  SET is_blocked = true,
      blocked_at = NOW(),
      blocked_reason = p_ban_reason
  WHERE id = p_user_id;

  RETURN ban_id;
END;
$$;


--
-- Name: create_policy_safe(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_policy_safe(p_policy_name text, p_table_name text, p_policy_definition text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_policy_exists BOOLEAN;
    v_table_exists BOOLEAN;
BEGIN
    -- Verificar si la tabla existe
    SELECT EXISTS(
        SELECT 1 FROM information_schema.tables
        WHERE table_schema = 'public'
        AND table_name = p_table_name
    ) INTO v_table_exists;

    -- Si la tabla no existe, salir
    IF NOT v_table_exists THEN
        RETURN;
    END IF;

    -- Verificar si la política ya existe
    SELECT EXISTS(
        SELECT 1 FROM pg_policies
        WHERE schemaname = 'public'
        AND tablename = p_table_name
        AND policyname = p_policy_name
    ) INTO v_policy_exists;

    -- Si no existe, crearla
    IF NOT v_policy_exists THEN
        BEGIN
            EXECUTE p_policy_definition;
        EXCEPTION WHEN OTHERS THEN
            -- Ignorar errores de políticas (columnas faltantes, etc.)
            NULL;
        END;
    END IF;
END;
$$;


--
-- Name: create_post(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_post(p_user_id uuid, p_profile_id uuid, p_content text, p_post_type text DEFAULT 'text'::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    new_post_id UUID;
    result JSON;
BEGIN
    INSERT INTO public.posts (user_id, profile_id, content, post_type)
    VALUES (p_user_id, p_profile_id, p_content, p_post_type)
    RETURNING id INTO new_post_id;

    SELECT json_build_object(
        'id', p.id,
        'user_id', p.user_id,
        'content', p.content,
        'post_type', p.post_type,
        'likes_count', p.likes_count,
        'created_at', p.created_at
    ) INTO result
    FROM public.posts p
    WHERE p.id = new_post_id;

    RETURN result;
END;
$$;


--
-- Name: create_post(uuid, uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_post(p_user_id uuid, p_profile_id uuid, p_content text, p_post_type text DEFAULT 'text'::text, p_image_url text DEFAULT NULL::text, p_video_url text DEFAULT NULL::text, p_location text DEFAULT NULL::text) RETURNS TABLE(id uuid, user_id uuid, profile_id uuid, content text, post_type text, image_url text, video_url text, location text, likes_count integer, comments_count integer, shares_count integer, created_at timestamp with time zone, updated_at timestamp with time zone, profile_name text, profile_avatar text, is_verified boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
    DECLARE
        new_post_id UUID;
    BEGIN
        INSERT INTO public.posts (
            user_id, profile_id, content, post_type,
            image_url, video_url, location
        ) VALUES (
            p_user_id, p_profile_id, p_content, p_post_type,
            p_image_url, p_video_url, p_location
        ) RETURNING posts.id INTO new_post_id;

        RETURN QUERY
        SELECT
            p.id,
            p.user_id,
            p.profile_id,
            p.content,
            p.post_type,
            p.image_url,
            p.video_url,
            p.location,
            p.likes_count,
            p.comments_count,
            p.shares_count,
            p.created_at,
            p.updated_at,
            pr.first_name as profile_name,
            pr.avatar_url as profile_avatar,
            pr.is_verified
        FROM public.posts p
        LEFT JOIN public.profiles pr ON p.profile_id = pr.id
        WHERE p.id = new_post_id;
    END;
    $$;


--
-- Name: create_stripe_customer_for_user(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_stripe_customer_for_user(p_email text DEFAULT NULL::text, p_name text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_stripe_customer_id TEXT;
BEGIN
  -- Verificar que el usuario ya tenga un customer
  SELECT stripe_customer_id INTO v_stripe_customer_id
  FROM public.user_stripe_customers
  WHERE user_id = auth.uid();
  
  IF v_stripe_customer_id IS NOT NULL THEN
    RETURN v_stripe_customer_id;  -- Ya existe, retornar
  END IF;
  
  -- Generar ID mock para customer (en producción, esto será real de Stripe)
  v_stripe_customer_id := 'cus_' || substr(md5(random()::text), 1, 20);
  
  -- Crear customer mock en tabla local
  INSERT INTO stripe.customers (id, email, name, metadata)
  VALUES (v_stripe_customer_id, p_email, p_name, p_metadata);
  
  -- Vincular al usuario
  INSERT INTO public.user_stripe_customers (user_id, stripe_customer_id)
  VALUES (auth.uid(), v_stripe_customer_id);
  
  RETURN v_stripe_customer_id;
END;
$$;


--
-- Name: FUNCTION create_stripe_customer_for_user(p_email text, p_name text, p_metadata jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_stripe_customer_for_user(p_email text, p_name text, p_metadata jsonb) IS 'Crea un customer en Stripe y lo vincula al usuario actual (security definer)';


