--
-- Name: detect_suspicious_activity(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detect_suspicious_activity(p_user_id uuid) RETURNS TABLE(is_suspicious boolean, reason text, severity text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_suspicious BOOLEAN := FALSE;
    v_reason TEXT := '';
    v_severity TEXT := 'low';
    v_multiple_ips INTEGER;
    v_high_request_rate INTEGER;
BEGIN
    -- Verificar múltiples IPs en corto tiempo
    SELECT COUNT(DISTINCT ip_address) INTO v_multiple_ips
    FROM public.rate_limits
    WHERE
        user_id = p_user_id
        AND window_start > NOW() - INTERVAL '1 hour';

    IF v_multiple_ips > 5 THEN
        v_suspicious := TRUE;
        v_reason := 'Múltiples IPs detectadas en 1 hora: ' || v_multiple_ips;
        v_severity := 'high';
    END IF;

    -- Verificar alta tasa de requests
    SELECT COUNT(*) INTO v_high_request_rate
    FROM public.rate_limits
    WHERE
        user_id = p_user_id
        AND window_start > NOW() - INTERVAL '5 minutes';

    IF v_high_request_rate > 500 THEN
        v_suspicious := TRUE;
        v_reason := COALESCE(v_reason || ', ', '') || 'Alta tasa de requests: ' || v_high_request_rate;
        v_severity := 'high';
    END IF;

    RETURN QUERY SELECT
        v_suspicious AS is_suspicious,
        v_reason AS reason,
        v_severity AS severity;
END;
$$;


--
-- Name: escape_html(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.escape_html(text text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    IF text IS NULL THEN
        RETURN NULL;
    END IF;

    -- Escapar caracteres HTML peligrosos
    RETURN replace(
        replace(
            replace(
                replace(
                    replace(text, '&', '&amp;'),
                    '<', '&lt;'
                ),
                '>', '&gt;'
            ),
            '"', '&quot;'
        ),
        '''', '&#39;'
    );
END;
$$;


