--
-- Name: expire_old_sessions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expire_old_sessions() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Mark sessions as inactive if they've expired
    -- Only if expires_at column exists
    IF EXISTS (SELECT 1 FROM information_schema.columns
               WHERE table_name = 'user_sessions' AND column_name = 'expires_at') THEN
        UPDATE user_sessions
        SET is_active = FALSE
        WHERE expires_at < NOW() AND is_active = TRUE;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: freeze_wallets_on_dispute(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.freeze_wallets_on_dispute() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    partner1_id UUID;
    partner2_id UUID;
BEGIN
    -- Obtener IDs de los partners
    SELECT partner_1_id, partner_2_id 
    INTO partner1_id, partner2_id
    FROM couple_profiles 
    WHERE id = NEW.couple_id;
    
    -- Congelar wallets de ambos partners
    UPDATE user_wallets 
    SET is_frozen = true 
    WHERE user_id IN (partner1_id, partner2_id);
    
    -- Cambiar estado de la pareja a FROZEN_DISPUTE
    UPDATE couple_profiles 
    SET status = 'FROZEN_DISPUTE' 
    WHERE id = NEW.couple_id;
    
    RETURN NEW;
END;
$$;


