CREATE FUNCTION public.get_couple_profile_by_user_id(user_uuid uuid) RETURNS TABLE(id uuid, couple_name text, couple_bio text, relationship_type public.relationship_type, partner1_id uuid, partner2_id uuid, couple_images text[], is_verified boolean, is_premium boolean, created_at timestamp with time zone, updated_at timestamp with time zone, partner1_first_name text, partner1_last_name text, partner1_age integer, partner1_bio text, partner1_gender text, partner2_first_name text, partner2_last_name text, partner2_age integer, partner2_bio text, partner2_gender text)
