--
-- Name: get_dispute_time_remaining(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_dispute_time_remaining(p_dispute_id uuid) RETURNS TABLE(hours_remaining integer, minutes_remaining integer, seconds_remaining integer, is_expired boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE
    deadline TIMESTAMPTZ;
    remaining_seconds INTEGER;
BEGIN
    SELECT deadline_at INTO deadline
    FROM couple_disputes 
    WHERE id = p_dispute_id;
    
    IF deadline IS NULL THEN
        RETURN QUERY SELECT 0, 0, 0, true;
        RETURN;
    END IF;
    
    remaining_seconds := EXTRACT(EPOCH FROM (deadline - NOW()))::INTEGER;
    
    IF remaining_seconds <= 0 THEN
        RETURN QUERY SELECT 0, 0, 0, true;
    ELSE
        RETURN QUERY SELECT 
            remaining_seconds / 3600,
            (remaining_seconds % 3600) / 60,
            remaining_seconds % 60,
            false;
    END IF;
END;
$$;


--
-- Name: FUNCTION get_dispute_time_remaining(p_dispute_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_dispute_time_remaining(p_dispute_id uuid) IS 'Calcula tiempo restante en formato HH:MM:SS para UI';


--
-- Name: get_expired_disputes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_expired_disputes() RETURNS TABLE(dispute_id uuid, couple_id uuid, deadline_at timestamp with time zone, hours_expired numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        cd.id as dispute_id,
        cd.couple_id,
        cd.deadline_at,
        EXTRACT(EPOCH FROM (NOW() - cd.deadline_at)) / 3600 as hours_expired
    FROM couple_disputes cd
    WHERE cd.status = 'PENDING_AGREEMENT'
      AND cd.deadline_at < NOW()
    ORDER BY cd.deadline_at ASC;
END;
$$;


--
-- Name: FUNCTION get_expired_disputes(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_expired_disputes() IS 'Obtiene disputas vencidas para procesamiento automático (cron job)';


--
-- Name: get_model_stats(character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_model_stats(p_model_version character varying, p_period_hours integer DEFAULT 24) RETURNS TABLE(total_predictions bigint, avg_score numeric, cache_hit_rate numeric, error_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    COUNT(*)::BIGINT as total_predictions,
    AVG(score)::DECIMAL(3,2) as avg_score,
    (SUM(CASE WHEN cache_hit THEN 1 ELSE 0 END)::DECIMAL / NULLIF(COUNT(*), 0))::DECIMAL(5,4) as cache_hit_rate,
    SUM(CASE WHEN error_message IS NOT NULL THEN 1 ELSE 0 END)::BIGINT as error_count
  FROM ai_prediction_logs
  WHERE model_version = p_model_version
    AND timestamp > NOW() - (p_period_hours || ' hours')::INTERVAL;
END;
$$;


--
-- Name: get_post_comments(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_post_comments(post_uuid uuid, page_limit integer DEFAULT 10, page_offset integer DEFAULT 0) RETURNS TABLE(id uuid, user_id uuid, profile_id uuid, parent_comment_id uuid, content text, likes_count integer, created_at timestamp with time zone, profile_name text, profile_avatar text, user_liked boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
    BEGIN
        RETURN QUERY
        SELECT
            c.id,
            c.user_id,
            c.profile_id,
            c.parent_comment_id,
            c.content,
            c.likes_count,
            c.created_at,
            pr.first_name as profile_name,
            pr.avatar_url as profile_avatar,
            EXISTS(
                SELECT 1 FROM public.comment_likes cl
                WHERE cl.comment_id = c.id AND cl.user_id = auth.uid()
            ) as user_liked
        FROM public.post_comments c
        LEFT JOIN public.profiles pr ON c.profile_id = pr.id
        WHERE c.post_id = post_uuid
        AND c.deleted_at IS NULL
        ORDER BY c.created_at ASC
        LIMIT page_limit OFFSET page_offset;
    END;
    $$;


--
-- Name: get_potential_matches(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_potential_matches(user_id_param uuid, limit_param integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    result JSONB;
BEGIN
    SELECT jsonb_agg(
        jsonb_build_object(
            'id', p.id,
            'name', p.name,
            'age', p.age,
            'bio', p.bio,
            'avatar_url', p.avatar_url,
            'interests', p.interests,
            'compatibility_score', RANDOM() * 100 -- Simulado por ahora
        )
    ) INTO result
    FROM profiles p
    WHERE p.id != user_id_param
    AND p.is_active = true
    AND p.is_blocked = false
    AND NOT EXISTS (
        SELECT 1 FROM matches m
        WHERE (m.user1_id = user_id_param AND m.user2_id = p.id)
        OR (m.user1_id = p.id AND m.user2_id = user_id_param)
    )
    LIMIT limit_param;

    RETURN COALESCE(result, '[]'::jsonb);
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'error', SQLERRM
    );
END;
$$;


