CREATE FUNCTION public.get_user_active_consents(p_user_id uuid) RETURNS TABLE(consent_type text, document_path text, consented_at timestamp with time zone, expires_at timestamp with time zone)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        uc.consent_type,
