--
-- Name: grant_worldid_verification_reward(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grant_worldid_verification_reward() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  reward_amt NUMERIC(20, 2);
BEGIN
  -- Recompensa base: 50 CMPX por orb, 25 CMPX por device
  reward_amt := CASE
    WHEN NEW.verification_level = 'orb' THEN 50.00
    WHEN NEW.verification_level = 'device' THEN 25.00
    ELSE 10.00
  END;

  -- Crear registro de recompensa
  INSERT INTO worldid_rewards (
    verification_id,
    user_id,
    reward_type,
    reward_amount,
    claimed,
    metadata
  ) VALUES (
    NEW.id,
    NEW.user_id,
    'cmpx',
    reward_amt,
    false,
    jsonb_build_object(
      'verification_level', NEW.verification_level,
      'verified_at', NEW.verified_at
    )
  );

  RETURN NEW;
END;
$$;


