--
-- Name: has_access_to_sensitive_data(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_access_to_sensitive_data(p_target_user_id uuid, p_data_type text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    -- El usuario siempre puede acceder a sus propios datos
    IF p_target_user_id = auth.uid() THEN
        RETURN TRUE;
    END IF;

    -- Los admins pueden acceder a cualquier dato
    IF EXISTS (
        SELECT 1 FROM public.admin_users
        WHERE user_id = auth.uid() AND is_active = TRUE
    ) THEN
        RETURN TRUE;
    END IF;

    -- Para datos específicos, verificar permisos adicionales
    CASE p_data_type
        WHEN 'email' THEN
            -- Solo el propio usuario y admins pueden ver emails
            RETURN FALSE;
        WHEN 'phone' THEN
            -- Solo el propio usuario y admins pueden ver teléfonos
            RETURN FALSE;
        WHEN 'financial' THEN
            -- Solo el propio usuario y admins pueden ver datos financieros
            RETURN FALSE;
        ELSE
            RETURN FALSE;
    END CASE;
END;
$$;


