--
-- Name: mask_email(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mask_email(email text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    local_part TEXT;
    domain TEXT;
BEGIN
    IF email IS NULL THEN
        RETURN NULL;
    END IF;

    -- Extraer local part y domain
    local_part := split_part(email, '@', 1);
    domain := split_part(email, '@', 2);

    -- Enmascarar local part (mostrar solo primeros 2 caracteres)
    IF length(local_part) > 2 THEN
        local_part := substring(local_part, 1, 2) || '***';
    ELSE
        local_part := '***';
    END IF;

    RETURN local_part || '@' || domain;
END;
$$;


--
-- Name: mask_sensitive_data(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mask_sensitive_data(data text, data_type text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    IF data IS NULL THEN
        RETURN NULL;
    END IF;

    CASE data_type
        WHEN 'email' THEN
            RETURN mask_email(data);
        WHEN 'phone' THEN
            -- Enmascarar número de teléfono
            IF length(data) > 4 THEN
                RETURN '***' || substring(data, length(data) - 3);
            ELSE
                RETURN '***';
            END IF;
        WHEN 'credit_card' THEN
            -- Enmascarar tarjeta de crédito
            IF length(data) > 4 THEN
                RETURN '****-****-****-' || substring(data, length(data) - 3);
            ELSE
                RETURN '****';
            END IF;
        ELSE
            RETURN '***';
    END CASE;
END;
$$;


--
-- Name: process_agreement_on_acceptance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_agreement_on_acceptance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Si hay propuesta y aceptación, marcar como resuelto
    IF NEW.proposed_winner_id IS NOT NULL AND NEW.winner_accepted_by IS NOT NULL THEN
        NEW.status = 'RESOLVED_TRANSFERRED';
        NEW.final_winner_id = NEW.proposed_winner_id;
        NEW.assets_transferred_at = NOW();
        
        -- Nota: La transferencia real de activos se hace en el servicio
    END IF;
    
    RETURN NEW;
END;
$$;


--
-- Name: process_referral_reward(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_referral_reward(referral_code_param text, new_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    inviter_record RECORD;
    inviter_tokens RECORD;
    new_user_tokens RECORD;
    referral_amount INTEGER := 50;
    welcome_amount INTEGER := 50;
    result JSONB;
BEGIN
    -- Buscar invitador por código
    SELECT ut.*, u.email
    INTO inviter_record
    FROM public.user_tokens ut
    JOIN auth.users u ON ut.user_id = u.id
    WHERE ut.referral_code = referral_code_param;

    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Código de referido inválido'
        );
    END IF;

    -- Verificar que no se auto-refiera
    IF inviter_record.user_id = new_user_id THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'No puedes referirte a ti mismo'
        );
    END IF;

    -- Verificar límite mensual del invitador
    IF (inviter_record.monthly_earned + referral_amount) > inviter_record.monthly_limit THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Límite mensual alcanzado (' || inviter_record.monthly_limit || ' CMPX)'
        );
    END IF;

    -- Actualizar tokens del invitador
    UPDATE public.user_tokens
    SET
        cmpx_balance = cmpx_balance + referral_amount,
        monthly_earned = monthly_earned + referral_amount,
        total_referrals = total_referrals + 1,
        updated_at = NOW()
    WHERE user_id = inviter_record.user_id;

    -- Actualizar tokens del nuevo usuario
    UPDATE public.user_tokens
    SET
        cmpx_balance = cmpx_balance + welcome_amount,
        referred_by = inviter_record.user_id,
        updated_at = NOW()
    WHERE user_id = new_user_id;

    -- Registrar transacciones
    INSERT INTO public.transactions (
        user_id, transaction_type, token_type, amount,
        balance_before, balance_after, description, related_user_id
    ) VALUES
    (
        inviter_record.user_id, 'referral_bonus', 'CMPX', referral_amount,
        inviter_record.cmpx_balance, inviter_record.cmpx_balance + referral_amount,
        'Recompensa por referir usuario', new_user_id
    ),
    (
        new_user_id, 'welcome_bonus', 'CMPX', welcome_amount,
        0, welcome_amount,
        'Bono de bienvenida por registro', inviter_record.user_id
    );

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Recompensas asignadas: ' || referral_amount || ' CMPX para invitador, ' || welcome_amount || ' CMPX de bienvenida',
        'inviter_reward', referral_amount,
        'welcome_bonus', welcome_amount
    );
END;
$$;


--
-- Name: process_stripe_webhook_event(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_stripe_webhook_event(p_stripe_event_id text, p_event_type text, p_event_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_result JSONB;
  v_customer_id TEXT;
  v_user_id UUID;
BEGIN
  -- Verificar si el evento ya fue procesado
  IF EXISTS (
    SELECT 1 FROM public.stripe_webhook_events
    WHERE stripe_event_id = p_stripe_event_id
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Event already processed'
    );
  END IF;
  
  -- Insertar evento
  INSERT INTO public.stripe_webhook_events (stripe_event_id, event_type, event_data)
  VALUES (p_stripe_event_id, p_event_type, p_event_data);
  
  -- Procesar según tipo de evento
  v_result := jsonb_build_object('success', true, 'message', 'Event received');
  
  -- Evento: payment_intent.succeeded
  IF p_event_type = 'payment_intent.succeeded' THEN
    -- Actualizar balance de tokens CMPX del usuario
    -- Aquí iría la lógica de recarga de tokens
    v_result := v_result || jsonb_build_object(
      'action', 'payment_succeeded',
      'message', 'Payment processed, tokens credited'
    );
  END IF;
  
  -- Evento: customer.subscription.updated
  IF p_event_type = 'customer.subscription.updated' THEN
    -- Actualizar estado de suscripción premium del usuario
    v_customer_id := p_event_data->'data'->'object'->'customer';
    
    SELECT user_id INTO v_user_id
    FROM public.user_stripe_customers
    WHERE stripe_customer_id = v_customer_id;
    
    -- Aquí iría la lógica para actualizar el estado premium
    v_result := v_result || jsonb_build_object(
      'action', 'subscription_updated',
      'user_id', v_user_id,
      'message', 'Subscription status updated'
    );
  END IF;
  
  -- Marcar como procesado
  UPDATE public.stripe_webhook_events
  SET processed = true,
      processed_at = NOW()
  WHERE stripe_event_id = p_stripe_event_id;
  
  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION process_stripe_webhook_event(p_stripe_event_id text, p_event_type text, p_event_data jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.process_stripe_webhook_event(p_stripe_event_id text, p_event_type text, p_event_data jsonb) IS 'Procesa eventos de webhook de Stripe (llamado desde Edge Functions)';


--
-- Name: record_gallery_commission(text, uuid, text, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_gallery_commission(p_gallery_id text, p_creator_id uuid, p_transaction_type text, p_amount_cmpx numeric, p_commission_percentage numeric DEFAULT 10.0) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_commission_amount NUMERIC;
  v_creator_amount NUMERIC;
  v_commission_id UUID;
BEGIN
  -- Calculate splits
  v_commission_amount := p_amount_cmpx * (p_commission_percentage / 100);
  v_creator_amount := p_amount_cmpx - v_commission_amount;

  -- Insert record
  INSERT INTO public.gallery_commissions (
    gallery_id,
    creator_id,
    transaction_type,
    amount_cmpx,
    commission_amount_cmpx,
    creator_amount_cmpx,
    commission_percentage
  ) VALUES (
    p_gallery_id,
    p_creator_id,
    p_transaction_type,
    p_amount_cmpx,
    v_commission_amount,
    v_creator_amount,
    p_commission_percentage
  ) RETURNING id INTO v_commission_id;

  RETURN v_commission_id;
END;
$$;


--
-- Name: record_gallery_commission(uuid, uuid, text, integer, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_gallery_commission(p_gallery_id uuid, p_creator_id uuid, p_transaction_type text, p_amount_cmpx integer, p_commission_percentage numeric DEFAULT 10.00) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
  commission_result RECORD;
  commission_id UUID;
BEGIN
  -- Calcular comisión
  SELECT * INTO commission_result
  FROM calculate_gallery_commission(p_amount_cmpx, p_commission_percentage);

  -- Crear registro de comisión
  INSERT INTO gallery_commissions (
    gallery_id,
    creator_id,
    transaction_type,
    amount_cmpx,
    commission_percentage,
    commission_amount_cmpx,
    creator_amount_cmpx
  ) VALUES (
    p_gallery_id,
    p_creator_id,
    p_transaction_type,
    p_amount_cmpx,
    p_commission_percentage,
    commission_result.commission_amount,
    commission_result.creator_amount
  )
  RETURNING id INTO commission_id;

  -- Otorgar tokens al creador (90%)
  UPDATE user_token_balances
  SET cmpx_balance = cmpx_balance + commission_result.creator_amount,
      updated_at = NOW()
  WHERE user_id = p_creator_id;

  -- Registrar transacción para el creador
  INSERT INTO token_transactions (
    user_id,
    transaction_type,
    token_type,
    amount,
    balance_after,
    description,
    metadata
  ) VALUES (
    p_creator_id,
    'earn',
    'cmpx',
    commission_result.creator_amount,
    (SELECT cmpx_balance FROM user_token_balances WHERE user_id = p_creator_id),
    'Comisión de galería (90%)',
    jsonb_build_object('gallery_id', p_gallery_id, 'transaction_type', p_transaction_type)
  );

  RETURN commission_id;
END;
$$;


--
-- Name: record_gallery_commission_internal(uuid, uuid, character varying, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_gallery_commission_internal(p_gallery_id uuid, p_creator_id uuid, p_transaction_type character varying, p_amount_cmpx numeric, p_commission_percentage numeric DEFAULT 10.0) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_commission_id UUID;
  v_commission_amount NUMERIC;
  v_creator_amount NUMERIC;
BEGIN
  -- Calculate commission
  SELECT commission_amount, creator_amount INTO v_commission_amount, v_creator_amount
  FROM calculate_gallery_commission(p_amount_cmpx, p_commission_percentage);

  -- Insert commission record
  INSERT INTO gallery_commissions (
    gallery_id,
    creator_id,
    transaction_type,
    amount_cmpx,
    commission_percentage,
    commission_amount_cmpx,
    creator_amount_cmpx
  ) VALUES (
    p_gallery_id,
    p_creator_id,
    p_transaction_type,
    p_amount_cmpx,
    p_commission_percentage,
    v_commission_amount,
    v_creator_amount
  ) RETURNING id INTO v_commission_id;

  -- Award tokens to creator (assuming user_token_balances table exists)
  -- This would be handled by the RPC function record_gallery_commission
  -- which calls this function and then updates the token balance

  RETURN v_commission_id;
END;
$$;


