--
-- Name: sanitize_input(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sanitize_input(input_text text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    -- Eliminar caracteres peligrosos
    RETURN regexp_replace(
        regexp_replace(
            regexp_replace(input_text, '''', '', 'g'),
            ';', '', 'g'
        ),
        '--', '', 'g'
    );
END;
$$;


--
-- Name: sanitize_profile_inputs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sanitize_profile_inputs() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    -- Sanitizar campos de texto (solo si existen)
    IF NEW.first_name IS NOT NULL THEN
        NEW.first_name := sanitize_input(NEW.first_name);
    END IF;

    IF NEW.last_name IS NOT NULL THEN
        NEW.last_name := sanitize_input(NEW.last_name);
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: sanitize_user_content(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sanitize_user_content(content text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    IF content IS NULL THEN
        RETURN NULL;
    END IF;

    -- Sanitizar contra inyección SQL y XSS
    RETURN escape_html(sanitize_input(content));
END;
$$;


--
-- Name: search_unified(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_unified(query_text text) RETURNS TABLE(id uuid, type text, title text, subtitle text, image_url text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
begin
  return query
    select
      p.id,
      'profile'::text as type,
      coalesce(p.email, '') as title,
      ''::text as subtitle,
      coalesce(p.avatar_url, '') as image_url
    from public.profiles p
    where
      query_text is not null
      and query_text <> ''
      and p.email ilike '%' || query_text || '%'
    order by similarity(coalesce(p.email, ''), query_text) desc
    limit 10;
end;
$$;


