--
-- Name: sync_stories_media_url(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_stories_media_url() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Si media_urls tiene valores y media_url está vacío, usar el primero
    IF NEW.media_urls IS NOT NULL AND array_length(NEW.media_urls, 1) > 0 AND 
       (NEW.media_url IS NULL OR NEW.media_url = '') THEN
        NEW.media_url := NEW.media_urls[1];
    END IF;
    
    -- Si media_url tiene valor y media_urls está vacío, crear array
    IF NEW.media_url IS NOT NULL AND NEW.media_url != '' AND 
       (NEW.media_urls IS NULL OR array_length(NEW.media_urls, 1) = 0) THEN
        NEW.media_urls := ARRAY[NEW.media_url];
    END IF;
    
    RETURN NEW;
END;
$$;


--
-- Name: toggle_post_like(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.toggle_post_like(p_post_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    existing_like_id UUID;
    profile_id_var UUID;
BEGIN
    SELECT id INTO profile_id_var FROM public.profiles WHERE user_id = p_user_id LIMIT 1;
    SELECT id INTO existing_like_id FROM public.post_likes WHERE post_id = p_post_id AND user_id = p_user_id;

    IF existing_like_id IS NOT NULL THEN
        DELETE FROM public.post_likes WHERE id = existing_like_id;
        UPDATE public.posts SET likes_count = likes_count - 1 WHERE id = p_post_id;
        RETURN FALSE;
    ELSE
        INSERT INTO public.post_likes (post_id, user_id, profile_id) VALUES (p_post_id, p_user_id, profile_id_var);
        UPDATE public.posts SET likes_count = likes_count + 1 WHERE id = p_post_id;
        RETURN TRUE;
    END IF;
END;
$$;


