--

CREATE FUNCTION public.update_club_checkin_count() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE clubs
  SET
    check_in_count = (
      SELECT COUNT(DISTINCT user_id)
      FROM club_checkins
      WHERE club_id = NEW.club_id AND is_verified = true
    ),
    updated_at = NOW()
  WHERE id = NEW.club_id;

  RETURN NEW;
END;
$$;


--
-- Name: update_club_rating_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_club_rating_stats() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  avg_rating FLOAT;
  total_reviews INTEGER;
BEGIN
  IF TG_OP = 'INSERT' OR TG_OP = 'UPDATE' THEN
    SELECT
      AVG(rating)::FLOAT,
      COUNT(*)
    INTO avg_rating, total_reviews
    FROM club_ratings
    WHERE club_id = NEW.club_id;

    UPDATE clubs
    SET
      average_rating = COALESCE(avg_rating, 0),
      total_reviews = total_reviews
    WHERE id = NEW.club_id;
  ELSIF TG_OP = 'DELETE' THEN
    SELECT
      AVG(rating)::FLOAT,
      COUNT(*)
    INTO avg_rating, total_reviews
    FROM club_ratings
    WHERE club_id = OLD.club_id;

    UPDATE clubs
    SET
      average_rating = COALESCE(avg_rating, 0),
      total_reviews = total_reviews
    WHERE id = OLD.club_id;
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: FUNCTION update_club_rating_stats(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.update_club_rating_stats() IS 'Trigger que actualiza automáticamente average_rating y total_reviews en la tabla clubs';


--
-- Name: update_club_ratings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_club_ratings() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Verificar si la tabla clubs tiene las columnas necesarias
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'clubs' AND column_name = 'average_rating') THEN
        UPDATE clubs 
        SET 
            average_rating = (
                SELECT COALESCE(AVG(rating), 0) 
                FROM club_reviews 
                WHERE club_id = COALESCE(NEW.club_id, OLD.club_id) 
                  AND verified = true
            ),
            total_reviews = (
                SELECT COUNT(*) 
                FROM club_reviews 
                WHERE club_id = COALESCE(NEW.club_id, OLD.club_id) 
                  AND verified = true
            ),
            updated_at = NOW()
        WHERE id = COALESCE(NEW.club_id, OLD.club_id);
    END IF;
    
    RETURN COALESCE(NEW, OLD);
END;
$$;


