--
-- Name: update_profile_score(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_profile_score(profile_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    report_count integer;
    new_score integer;
    new_status public.profile_score_status;
BEGIN
    -- Contar reportes válidos ('resolved') contra el usuario
    SELECT count(*) INTO report_count
    FROM public.reports
    WHERE reported_user_id = profile_id AND status = 'resolved';

    -- Lógica de cálculo de score (10 puntos por reporte resuelto)
    new_score := 100 - (report_count * 10);
    IF new_score < 0 THEN
        new_score := 0;
    END IF;

    -- Determinar el estado del semáforo
    IF new_score >= 80 THEN
        new_status := 'green';
    ELSIF new_score >= 50 THEN
        new_status := 'yellow';
    ELSE
        new_status := 'red';
    END IF;

    -- Actualizar la tabla de perfiles
    UPDATE public.profiles
    SET
        score = new_score,
        score_status = new_status
    WHERE id = profile_id;

END;
$$;


--
-- Name: FUNCTION update_profile_score(profile_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.update_profile_score(profile_id uuid) IS 'Calcula y actualiza el score de reputación y el estado de un perfil basado en reportes válidos.';


