--
-- Name: update_user_level(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_user_level() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  new_level VARCHAR(20);
  calculated_points INTEGER;
BEGIN
  -- Calcular total_points manualmente (porque es columna generada)
  calculated_points := NEW.daily_activity_points + NEW.referral_points + 
                       NEW.content_points + NEW.engagement_points + NEW.mission_points;
  
  -- Determinar nivel según puntos totales
  IF calculated_points >= 10000 THEN
    new_level := 'diamond';
  ELSIF calculated_points >= 3000 THEN
    new_level := 'gold';
  ELSIF calculated_points >= 1000 THEN
    new_level := 'silver';
  ELSE
    new_level := 'bronze';
  END IF;
  
  -- Actualizar solo si cambió
  IF NEW.level != new_level THEN
    NEW.level := new_level;
    NEW.updated_at := NOW();
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: update_user_token_balance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_user_token_balance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Update user_token_balances table based on transaction
    INSERT INTO user_token_balances (user_id, cmpx_balance, gtk_balance, updated_at)
    VALUES (
        NEW.user_id,
        CASE WHEN NEW.token_type = 'CMPX' AND NEW.transaction_type = 'deposit' THEN NEW.amount ELSE 0 END,
        CASE WHEN NEW.token_type = 'GTK' AND NEW.transaction_type = 'deposit' THEN NEW.amount ELSE 0 END,
        NEW.created_at
    )
    ON CONFLICT (user_id)
    DO UPDATE SET
        cmpx_balance = CASE
            WHEN NEW.token_type = 'CMPX' AND NEW.transaction_type = 'deposit' THEN user_token_balances.cmpx_balance + NEW.amount
            WHEN NEW.token_type = 'CMPX' AND NEW.transaction_type = 'withdrawal' THEN user_token_balances.cmpx_balance - NEW.amount
            ELSE user_token_balances.cmpx_balance
        END,
        gtk_balance = CASE
            WHEN NEW.token_type = 'GTK' AND NEW.transaction_type = 'deposit' THEN user_token_balances.gtk_balance + NEW.amount
            WHEN NEW.token_type = 'GTK' AND NEW.transaction_type = 'withdrawal' THEN user_token_balances.gtk_balance - NEW.amount
            ELSE user_token_balances.gtk_balance
        END,
        updated_at = NEW.created_at;

    RETURN NEW;
END;
$$;


