--
-- Name: security_flags; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.security_flags (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    user_id uuid NOT NULL,
    flag_type character varying(50) NOT NULL,
    severity character varying(20) NOT NULL,
    description text NOT NULL,
    confidence integer NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb,
    is_resolved boolean DEFAULT false,
    resolved_at timestamp with time zone,
    resolved_by uuid,
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT security_flags_confidence_check CHECK (((confidence >= 0) AND (confidence <= 100))),
    CONSTRAINT security_flags_flag_type_check CHECK (((flag_type)::text = ANY (ARRAY[('suspicious_login'::character varying)::text, ('multiple_devices'::character varying)::text, ('unusual_activity'::character varying)::text, ('fraud_pattern'::character varying)::text, ('account_compromise'::character varying)::text]))),
    CONSTRAINT security_flags_severity_check CHECK (((severity)::text = ANY (ARRAY[('low'::character varying)::text, ('medium'::character varying)::text, ('high'::character varying)::text, ('critical'::character varying)::text])))
);


--
-- Name: active_security_flags; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.active_security_flags AS
 SELECT sf.id,
    sf.user_id,
    sf.flag_type,
    sf.severity,
    sf.description,
    sf.confidence,
    sf.created_at,
    'Usuario'::text AS first_name,
    'Anónimo'::text AS last_name
   FROM public.security_flags sf
  WHERE (sf.is_resolved = false)
  ORDER BY sf.severity DESC, sf.confidence DESC;


