    user_id uuid NOT NULL,
    reward_type character varying(20) DEFAULT 'cmpx'::character varying NOT NULL,
    reward_amount numeric(20,2) DEFAULT 0 NOT NULL,
    claimed boolean DEFAULT false,
    claimed_at timestamp with time zone,
    transaction_id uuid,
    metadata jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT worldid_rewards_reward_type_check CHECK (((reward_type)::text = ANY (ARRAY[('cmpx'::character varying)::text, ('gtk'::character varying)::text])))
);


