-- Name: worldid_verifications; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.worldid_verifications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    verification_level character varying(20) DEFAULT 'orb'::character varying NOT NULL,
    verified_at timestamp with time zone DEFAULT now(),
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    action_id text NOT NULL,
    expires_at timestamp with time zone,
    is_active boolean DEFAULT true,
    merkle_root text,
    metadata jsonb DEFAULT '{}'::jsonb,
    nullifier_hash text NOT NULL,
    proof jsonb NOT NULL,
    signal_hash text,
    CONSTRAINT worldid_verifications_verification_level_check CHECK (((verification_level)::text = ANY (ARRAY[('orb'::character varying)::text, ('device'::character varying)::text])))
);


--
-- Name: active_worldid_verifications; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.active_worldid_verifications AS
 SELECT v.id,
    v.user_id,
    v.nullifier_hash,
    v.verification_level,
    v.proof,
    v.merkle_root,
    v.action_id,
    v.signal_hash,
    v.verified_at,
    v.expires_at,
    v.is_active,
    v.metadata,
    v.created_at,
    v.updated_at,
    r.reward_amount,
    r.claimed,
    r.claimed_at
   FROM (public.worldid_verifications v
     LEFT JOIN public.worldid_rewards r ON ((v.id = r.verification_id)))
  WHERE ((v.is_active = true) AND ((v.expires_at IS NULL) OR (v.expires_at > now())));


