-- Name: ai_compatibility_scores; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ai_compatibility_scores (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user1_id uuid NOT NULL,
    user2_id uuid NOT NULL,
    ai_score numeric(3,2),
    legacy_score numeric(3,2),
    final_score numeric(3,2) NOT NULL,
    model_version character varying(50) DEFAULT 'v1-base'::character varying,
    prediction_method character varying(20),
    confidence_score numeric(3,2),
    features jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT ai_compatibility_scores_ai_score_check CHECK (((ai_score IS NULL) OR ((ai_score >= (0)::numeric) AND (ai_score <= (1)::numeric)))),
    CONSTRAINT ai_compatibility_scores_confidence_score_check CHECK (((confidence_score IS NULL) OR ((confidence_score >= (0)::numeric) AND (confidence_score <= (1)::numeric)))),
    CONSTRAINT ai_compatibility_scores_final_score_check CHECK (((final_score >= (0)::numeric) AND (final_score <= (1)::numeric))),
