CREATE TABLE public.couple_gifts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    sender_couple_id uuid,
    receiver_couple_id uuid,
    gift_type text NOT NULL,
    gift_name text NOT NULL,
    gift_description text,
    gift_value numeric(10,2),
    is_delivered boolean DEFAULT false,
    delivery_date timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT couple_gifts_gift_type_check CHECK ((gift_type = ANY (ARRAY['virtual'::text, 'real'::text, 'experience'::text])))
);


--
-- Name: couple_interactions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.couple_interactions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    couple_id uuid,
    target_couple_id uuid,
    interaction_type text NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    metadata jsonb DEFAULT '{}'::jsonb,
    CONSTRAINT couple_interactions_interaction_type_check CHECK ((interaction_type = ANY (ARRAY['view'::text, 'like'::text, 'message'::text, 'wink'::text, 'gift'::text])))
);


--
-- Name: couple_matches; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.couple_matches (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    couple1_id uuid,
    couple2_id uuid,
    match_score numeric(3,2),
    compatibility_factors jsonb DEFAULT '{}'::jsonb,
    match_reasons text[] DEFAULT '{}'::text[],
    created_at timestamp with time zone DEFAULT now(),
    status text NOT NULL,
    CONSTRAINT couple_matches_match_score_check CHECK (((match_score >= (0)::numeric) AND (match_score <= (1)::numeric))),
    CONSTRAINT couple_matches_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'accepted'::text, 'rejected'::text, 'expired'::text])))
);


--
-- Name: couple_messages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.couple_messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    sender_couple_id uuid,
    receiver_couple_id uuid,
    message text NOT NULL,
    message_type text NOT NULL,
    is_read boolean DEFAULT false,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT couple_messages_message_type_check CHECK ((message_type = ANY (ARRAY['text'::text, 'image'::text, 'video'::text, 'gift'::text])))
);


--
-- Name: couple_nft_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.couple_nft_requests (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    token_id bigint NOT NULL,
    partner1_address character varying(42) NOT NULL,
    partner2_address character varying(42) NOT NULL,
    initiator_address character varying(42) NOT NULL,
    metadata_uri text NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb,
    consent1_timestamp timestamp with time zone,
    consent2_timestamp timestamp with time zone,
    status character varying(20) DEFAULT 'pending'::character varying NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    expires_at timestamp with time zone NOT NULL,
    blockchain_status text DEFAULT 'pending'::text,
    transaction_hash character varying(66),
    CONSTRAINT couple_nft_requests_blockchain_status_check CHECK ((blockchain_status = ANY (ARRAY['pending'::text, 'minting'::text, 'minted'::text, 'failed'::text]))),
    CONSTRAINT couple_nft_requests_check CHECK (((partner1_address)::text <> (partner2_address)::text)),
    CONSTRAINT couple_nft_requests_check1 CHECK ((((initiator_address)::text = (partner1_address)::text) OR ((initiator_address)::text = (partner2_address)::text))),
    CONSTRAINT couple_nft_requests_status_check CHECK (((status)::text = ANY (ARRAY[('pending'::character varying)::text, ('approved'::character varying)::text, ('minted'::character varying)::text, ('cancelled'::character varying)::text, ('expired'::character varying)::text])))
);


--
-- Name: TABLE couple_nft_requests; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.couple_nft_requests IS 'Solicitudes de NFT de pareja con sistema de consentimiento doble';


