    CONSTRAINT couple_profile_reports_status_check CHECK (((status)::text = ANY (ARRAY[('pending'::character varying)::text, ('reviewed'::character varying)::text, ('resolved'::character varying)::text, ('dismissed'::character varying)::text])))
);


