CREATE MATERIALIZED VIEW stripe.mv_prices AS
 SELECT p.id,
    p.product_id,
    p.nickname,
    p.currency,
    p.unit_amount,
    p.type,
    p.recurring_interval,
    p.recurring_interval_count,
    p.metadata,
    p.created,
    p.updated
   FROM (stripe.prices p
     JOIN stripe.mv_products pr ON ((p.product_id = pr.id)))
